/* Xing Mandarin — data tata bahasa HSK 1-6
   116 poin, hasil parse dari dokumen Grammar HSK 1-6 (Google Drive)
   Struktur: {hsk, title, hanzi, pinyin, desc, formula, examples:[{hz,py,id}]}
   Data statis — tidak per-user, tidak butuh Supabase. */
window.GRAMMAR_DATA = [{"hsk":1,"title":"是 shì","hanzi":"是","pinyin":"shì","desc":"Dipakai untuk menyatakan “adalah”.","formula":"Subjek + 是 + Kata Benda","examples":[{"hz":"我是学生。","py":"Wǒ shì xué sheng.","id":"Saya adalah murid."},{"hz":"他是老师。","py":"Tā shì lǎo shī.","id":"Dia adalah guru."}]},{"hsk":1,"title":"不 bù","hanzi":"不","pinyin":"bù","desc":"Dipakai untuk kalimat negatif, yang di mana arti kata 不 bù adalah tidak/bukan.","formula":"Subjek + 不 + Kata Kerja/Kata Sifat","examples":[{"hz":"我不喝茶。","py":"Wǒ bù hē chá.","id":"Saya tidak minum teh."},{"hz":"今天天气不好。","py":"Jīn tiān tiān qì bù hǎo.","id":"Cuaca hari ini tidak bagus."}]},{"hsk":1,"title":"吗 ma","hanzi":"吗","pinyin":"ma","desc":"Dipakai untuk membuat pertanyaan “apakah”, diletakkan di akhir kalimat.","formula":"Kalimat + 吗?","examples":[{"hz":"你是中国人吗？","py":"Nǐ shì Zhōng guó rén ma?","id":"Apakah kamu orang Tiongkok?"},{"hz":"他忙吗？","py":"Tā máng ma?","id":"Apakah dia sibuk?"}]},{"hsk":1,"title":"呢 ne","hanzi":"呢","pinyin":"ne","desc":"Dipakai untuk “kalau…” atau menanyakan balik, 呢 juga sering dipakai di percakapan agar tidak terdengar terlalu kaku.","formula":"Kalimat/Kalimat Tanya/Kata + 呢","examples":[{"hz":"我很好，你呢？","py":"Wǒ hěn hǎo, nǐ ne?","id":"Saya baik, kalau kamu?"},{"hz":"她在睡觉呢。","py":"Tā zài shuì jiào ne.","id":"Dia sedang tidur."}]},{"hsk":1,"title":"有 yǒu atau 没有 méi yǒu","hanzi":"有…没有","pinyin":"yǒu…méi yǒu","desc":"Dipakai untuk menyatakan punya atau tidak punya.","formula":"Subjek + 有/没有 + Kata Benda","examples":[{"hz":"我有一本书。","py":"Wǒ yǒu yì běn shū.","id":"Saya punya satu buah buku."},{"hz":"我没有钱。","py":"Wǒ méi yǒu qián.","id":"Saya tidak punya uang."}]},{"hsk":1,"title":"在 zài","hanzi":"在","pinyin":"zài","desc":"Dipakai untuk menyatakan lokasi.","formula":"Subjek + 在 + Tempat + Kata Kerja + Objek","examples":[{"hz":"我在学校学习中文。","py":"Wǒ zài xué xiào xué xí zhōng wén.","id":"Saya belajar bahasa Mandarin di sekolah."},{"hz":"他在家喝牛奶。","py":"Tā zài jiā hē níu nǎi.","id":"Dia minum susu di rumah."}]},{"hsk":1,"title":"了 le","hanzi":"了","pinyin":"le","desc":"Dipakai untuk menyatakan aksi suatu kejadian sudah selesai.","formula":"Subjek + Kata Kerja + 了","examples":[{"hz":"我吃饭了。","py":"Wǒ chī fàn le.","id":"Saya sudah makan."},{"hz":"她来了。","py":"Tā lái le.","id":"Dia sudah datang."}]},{"hsk":1,"title":"很 hěn","hanzi":"很","pinyin":"hěn","desc":"Dalam bahasa Mandarin, adjective (kata sifat) biasanya memakai 很, 很 bisa juga diartikan sebagai sangat.","formula":"Subjek + 很 + Kata Sifat","examples":[{"hz":"我很忙。","py":"Wǒ hěn máng.","id":"Saya sibuk."},{"hz":"学校很大。","py":"Xué xiào hěn dà.","id":"Sekolah sangat besar."}]},{"hsk":1,"title":"量词 liàng cí","hanzi":"量词","pinyin":"liàng cí","desc":"Dalam bahasa Mandarin, saat menghitung benda atau orang, harus memakai kata bantu bilangan (measure word) di antara angka dan noun.","formula":"Angka + Kata Satuan + Kata Benda","examples":[{"hz":"一个学生","py":"Yí gè xué sheng","id":"Seorang murid"},{"hz":"三本书","py":"Sān běn shū","id":"Tiga buah buku"}]},{"hsk":1,"title":"的 de","hanzi":"的","pinyin":"de","desc":"Dipakai untuk menunjukkan kepunyaan atau menjelaskan noun.","formula":"Kata Benda + 的 + Kata Benda","examples":[{"hz":"这是我的书。","py":"Zhè shì wǒ de shū.","id":"Ini adalah buku saya."},{"hz":"他是我的朋友。","py":"Tā shì wǒ de péng you.","id":"Dia adalah teman saya."}]},{"hsk":2,"title":"因为…所以… yīn wèi…suǒ yǐ…","hanzi":"因为…所以…","pinyin":"…… yīn wèi…suǒ yǐ…","desc":"Dipakai untuk menyatakan hubungan sebab dan akibat (karena… maka…).","formula":"因为 + Alasan，所以 + Hasil","examples":[{"hz":"因为今天下雨，所以我没去学校。","py":"Yīn wèi jīn tiān xià yǔ，suǒ yǐ wǒ méi qù xué xiào.","id":"Karena hari ini hujan, maka saya tidak pergi ke sekolah."},{"hz":"因为他很忙，所以不能来。","py":"Yīn wèi tā hěn máng，suǒ yǐ bù néng lái.","id":"Karena dia sangat sibuk, maka dia tidak bisa datang."}]},{"hsk":2,"title":"虽然…但是… suī rán…dàn shì…","hanzi":"虽然…但是…","pinyin":"…… suī rán…dàn shì…","desc":"Dipakai untuk menyatakan pertentangan (walaupun… tetapi…).","formula":"虽然 + Kondisi，但是 + Hasil","examples":[{"hz":"虽然很累，但是我还要学习。","py":"Suī rán hěn lèi，dàn shì wǒ hái yào xué xí.","id":"Walaupun lelah, saya tetap harus belajar."},{"hz":"虽然今天很冷，但是他没穿外套。","py":"Suī rán jīn tiān hěn lěng，dàn shì tā méi chuān wài tào.","id":"Walaupun hari ini dingin, tetapi dia tidak memakai jaket."}]},{"hsk":2,"title":"一边…一边… yì biān…yì biān","hanzi":"一边…一边…","pinyin":"…… yì biān…yì biān","desc":"Dipakai untuk menyatakan dua kegiatan dilakukan secara bersamaan.","formula":"一边 + Kata Kerja，一边 + Kata Kerja","examples":[{"hz":"我一边吃饭，一边看电视。","py":"Wǒ yì biān chī fàn，yì biān kàn diàn shì.","id":"Saya makan sambil menonton TV."},{"hz":"她一边听音乐，一边做作业。","py":"Tā yì biān tīng yīn yuè，yì biān zuò zuò yè.","id":"Dia mendengarkan musik sambil mengerjakan PR."}]},{"hsk":2,"title":"先…然后… xiān…rán hòu…","hanzi":"先…然后…","pinyin":"…… xiān…rán hòu…","desc":"Dipakai untuk menyatakan urutan kegiatan.","formula":"先 + Kegiatan 1，然后 + Kegiatan 2","examples":[{"hz":"我先吃饭，然后学习。","py":"Wǒ xiān chī fàn，rán hòu xué xí.","id":"Saya makan dulu, lalu belajar."},{"hz":"我们先买票，然后进去。","py":"Wǒ men xiān mǎi piào，rán hòu jìn qù.","id":"Kami membeli tiket dulu, lalu masuk."}]},{"hsk":2,"title":"又…又… yòu…yòu…","hanzi":"又…又…","pinyin":"…… yòu…yòu…","desc":"Dipakai untuk menyatakan dua sifat atau dua keadaan yang dimiliki sekaligus.","formula":"又 + Kata Sifat/Kata Kerja，又 + Kata Sifat/Kata Kerja","examples":[{"hz":"她又漂亮又聪明。","py":"Tā yòu piào liang yòu cōng ming.","id":"Dia cantik dan pintar."},{"hz":"这个苹果又大又甜。","py":"Zhè gè píng guǒ yòu dà yòu tián.","id":"Apel ini besar dan manis."}]},{"hsk":2,"title":"越来越… yùe lái yuè…","hanzi":"越来越…","pinyin":"… yùe lái yuè…","desc":"Dipakai untuk menyatakan perubahan yang semakin meningkat.","formula":"越来越 + Kata Sifat","examples":[{"hz":"天气越来越冷。","py":"Tiān qì yuè lái yuè lěng.","id":"Cuaca semakin dingin."},{"hz":"中文越来越难。","py":"Zhōng wén yuè lái yuè nán.","id":"Bahasa Mandarin semakin sulit."}]},{"hsk":2,"title":"从…到… cóng…dào…","hanzi":"从…到…","pinyin":"…… cóng…dào…","desc":"Dipakai untuk menyatakan rentang waktu atau tempat.","formula":"从 + A，到 + B","examples":[{"hz":"我从八点学习到十点。","py":"Wǒ cóng bā diǎn xué xí dào shí diǎn.","id":"Saya belajar dari jam delapan sampai jam sepuluh."},{"hz":"我从家走到学校。","py":"Wǒ cóng jiā zǒu dào xué xiào.","id":"Saya berjalan dari rumah ke sekolah."}]},{"hsk":2,"title":"比 bǐ","hanzi":"比","pinyin":"bǐ","desc":"Dipakai untuk membandingkan dua orang atau benda.","formula":"A + 比 + B + Kata Sifat","examples":[{"hz":"我比他高。","py":"Wǒ bǐ tā gāo.","id":"Saya lebih tinggi daripada dia."},{"hz":"今天比昨天热。","py":"Jīn tiān bǐ zuó tiān rè.","id":"Hari ini lebih panas daripada kemarin."}]},{"hsk":2,"title":"离 lí","hanzi":"离","pinyin":"lí","desc":"Dipakai untuk menyatakan jarak antara dua tempat.","formula":"A + 离 + B + Kata Sifat (近 / 远)","examples":[{"hz":"学校离我家很近。","py":"Xué xiào lí wǒ jiā hěn jìn.","id":"Sekolah dekat dengan rumah saya."},{"hz":"医院离这里很远。","py":"Yī yuàn lí zhè lǐ hěn yuǎn.","id":"Rumah sakit jauh dari sini."}]},{"hsk":2,"title":"正在… zhèng zài","hanzi":"正在…","pinyin":"… zhèng zài","desc":"Dipakai untuk menyatakan kegiatan yang sedang berlangsung.","formula":"Subjek + 正在 + Kata Kerja","examples":[{"hz":"我正在看书。","py":"Wǒ zhèng zài kàn shū.","id":"Saya sedang membaca buku."},{"hz":"老师正在上课。","py":"Lǎo shī zhèng zài shàng kè.","id":"Guru sedang mengajar."}]},{"hsk":2,"title":"已经…了 yǐ jīng…le","hanzi":"已经…了…","pinyin":"… yǐ jīng…le","desc":"Dipakai untuk menyatakan suatu kegiatan sudah selesai.","formula":"Subjek + 已经 + Kata Kerja + 了","examples":[{"hz":"我已经吃饭了。","py":"Wǒ yǐ jīng chī fàn le.","id":"Saya sudah makan."},{"hz":"他已经回家了。","py":"Tā yǐ jīng huí jiā le.","id":"Dia sudah pulang."}]},{"hsk":2,"title":"再 zài","hanzi":"再","pinyin":"zài","desc":"Dipakai untuk menyatakan melakukan sesuatu lagi di masa depan.","formula":"再 + Kata Kerja","examples":[{"hz":"请再说一次。","py":"Qǐng zài shuō yí cì.","id":"Tolong katakan sekali lagi."},{"hz":"我明天再来。","py":"Wǒ míng tiān zài lái.","id":"Saya akan datang lagi besok."}]},{"hsk":2,"title":"了 le","hanzi":"了","pinyin":"le","desc":"Dipakai untuk menyatakan perubahan keadaan atau situasi baru.","formula":"Subjek + … + 了","examples":[{"hz":"天黑了。","py":"Tiān hēi le.","id":"Hari sudah gelap."},{"hz":"我饿了。","py":"Wǒ è le.","id":"Saya lapar."}]},{"hsk":2,"title":"就 jiù","hanzi":"就","pinyin":"jiù","desc":"Dipakai untuk menyatakan sesuatu terjadi segera, langsung, atau lebih awal dari yang diperkirakan.","formula":"Subjek + 就 + Kata Kerja","examples":[{"hz":"我马上就来。","py":"Wǒ mǎ shàng jiù lái.","id":"Saya akan segera datang."},{"hz":"他八点就到学校了。","py":"Tā bā diǎn jiù dào xué xiào le.","id":"Dia sudah tiba di sekolah pukul delapan."}]},{"hsk":2,"title":"往 wǎng","hanzi":"往","pinyin":"wǎng","desc":"Dipakai untuk menyatakan arah atau tujuan gerakan.","formula":"往 + Tempat/Arah + Kata Kerja","examples":[{"hz":"请往前走。","py":"Qǐng wǎng qián zǒu.","id":"Silakan berjalan ke depan."},{"hz":"我们往学校走。","py":"Wǒ men wǎng xué xiào zǒu.","id":"Kami berjalan menuju sekolah."}]},{"hsk":2,"title":"得 de","hanzi":"得","pinyin":"de","desc":"Dipakai untuk menjelaskan hasil atau tingkat suatu tindakan.","formula":"Kata Kerja + 得 + Kata Sifat","examples":[{"hz":"她说得很好。","py":"Tā shuō de hěn hǎo.","id":"Dia berbicara dengan sangat baik."},{"hz":"他跑得很快。","py":"Tā pǎo de hěn kuài.","id":"Dia berlari sangat cepat."}]},{"hsk":2,"title":"吧 ba","hanzi":"吧","pinyin":"ba","desc":"Dipakai untuk memberikan saran, ajakan, atau dugaan, diletakkan di akhir kalimat.","formula":"Kalimat + 吧","examples":[{"hz":"我们一起去吧。","py":"Wǒ men yì qǐ qù ba.","id":"Mari kita pergi bersama."},{"hz":"休息一下吧。","py":"Xiū xi yí xià ba.","id":"Mari istirahat sebentar."}]},{"hsk":2,"title":"过 guo","hanzi":"过","pinyin":"guo","desc":"Dipakai untuk menyatakan pengalaman yang pernah dilakukan.","formula":"Subjek + Kata Kerja + 过 + Objek","examples":[{"hz":"我去过北京。","py":"Wǒ qù guo Běi jīng.","id":"Saya pernah pergi ke Beijing."},{"hz":"你吃过这个吗？","py":"Nǐ chī guo zhè gè ma?","id":"Apakah kamu pernah makan ini?"}]},{"hsk":2,"title":"着 zhe","hanzi":"着","pinyin":"zhe","desc":"Dipakai untuk menyatakan keadaan yang sedang berlangsung atau tetap.","formula":"Kata Kerja + 着","examples":[{"hz":"门开着。","py":"Mén kāi zhe.","id":"Pintunya terbuka."},{"hz":"他站着。","py":"Tā zhàn zhe.","id":"Dia sedang berdiri."}]},{"hsk":2,"title":"给 gěi","hanzi":"给","pinyin":"gěi","desc":"Dipakai untuk menyatakan memberi kepada seseorang atau melakukan sesuatu untuk seseorang.","formula":"给 + Orang + Benda / Kata Kerja","examples":[{"hz":"我给你一本书。","py":"Wǒ gěi nǐ yì běn shū.","id":"Saya memberi kamu sebuah buku."},{"hz":"请给我打电话。","py":"Qǐng gěi wǒ dǎ diàn huà.","id":"Tolong telepon saya."}]},{"hsk":2,"title":"让 ràng","hanzi":"让","pinyin":"ràng","desc":"Dipakai untuk menyatakan membiarkan atau menyuruh seseorang melakukan sesuatu.","formula":"A + 让 + B + Kata Kerja","examples":[{"hz":"老师让我回答问题。","py":"Lǎo shī ràng wǒ huí dá wèn tí.","id":"Guru menyuruh saya menjawab pertanyaan."},{"hz":"请让我看看。","py":"Qǐng ràng wǒ kàn kan.","id":"Tolong biarkan saya melihat."}]},{"hsk":2,"title":"对 duì","hanzi":"对","pinyin":"duì","desc":"Dipakai untuk menyatakan sikap atau tindakan terhadap atau kepada seseorang atau sesuatu.","formula":"A + 对 + B + Kata Sifat / Kata Kerja","examples":[{"hz":"他对我很好。","py":"Tā duì wǒ hěn hǎo.","id":"Dia sangat baik kepada saya."},{"hz":"老师对学生很认真。","py":"Lǎo shī duì xué sheng hěn rèn zhēn.","id":"Guru sangat serius terhadap murid-murid."}]},{"hsk":3,"title":"为了 wèi le…","hanzi":"为了…","pinyin":"wèi le…","desc":"Dipakai untuk menyatakan tujuan atau demi melakukan sesuatu.","formula":"为了 + Tujuan，Subjek + Kata Kerja","examples":[{"hz":"为了考试，我每天学习。","py":"Wèi le kǎo shì，wǒ měi tiān xué xí.","id":"Demi ujian, saya belajar setiap hari."},{"hz":"为了身体健康，他每天运动。","py":"Wèi le shēn tǐ jiàn kāng，tā měi tiān yùn dòng.","id":"Demi kesehatan, dia berolahraga setiap hari."}]},{"hsk":3,"title":"把 bǎ","hanzi":"把","pinyin":"bǎ","desc":"Dipakai untuk menekankan objek yang dikenai tindakan, di bahasa Indonesia seperti me- (kalimat aktif).","formula":"Subjek + 把 + Objek + Kata Kerja + Pelengkap","examples":[{"hz":"我把门关了。","py":"Wǒ bǎ mén guān le.","id":"Saya menutup pintu."},{"hz":"请把书放在桌子上。","py":"Qǐng bǎ shū fàng zài zhuō zi shàng.","id":"Tolong letakkan buku di atas meja."}]},{"hsk":3,"title":"被 bèi","hanzi":"被","pinyin":"bèi","desc":"Dipakai untuk menyatakan subjek yang menerima tindakan, di bahasa Indonesia seperti di- (kalimat pasif).","formula":"Subjek + 被 + Pelaku + Kata Kerja","examples":[{"hz":"我的手机被弟弟拿走了。","py":"Wǒ de shǒu jī bèi dì di ná zǒu le.","id":"Ponsel saya dibawa oleh adik laki-laki saya."},{"hz":"门被风打开了。","py":"Mén bèi fēng dǎ kāi le.","id":"Pintu dibuka oleh angin."}]},{"hsk":3,"title":"一…就… yī…jiù…","hanzi":"一…就…","pinyin":"…… yī…jiù…","desc":"Dipakai untuk menyatakan bahwa sesuatu langsung terjadi setelah hal lain terjadi.","formula":"一 + Kata Kerja 1，就 + Kata Kerja 2","examples":[{"hz":"我一下课就回家。","py":"Wǒ yí xià kè jiù huí jiā.","id":"Begitu kelas selesai, saya langsung pulang."},{"hz":"他一起床就喝水。","py":"Tā yì qǐ chuáng jiù hē shuǐ.","id":"Begitu bangun tidur, dia langsung minum air."}]},{"hsk":3,"title":"地 de","hanzi":"地","pinyin":"de","desc":"Dipakai untuk mengubah kata sifat menjadi keterangan cara (adverb).","formula":"Kata Sifat + 地 + Kata Kerja","examples":[{"hz":"他高兴地笑了。","py":"Tā gāo xìng de xiào le.","id":"Dia tersenyum dengan gembira."},{"hz":"这个苹果又大又甜。","py":"Zhè gè píng guǒ yòu dà yòu tián.","id":"Apel ini besar dan manis."}]},{"hsk":3,"title":"先…再… xiān…zài…","hanzi":"先…再…","pinyin":"…… xiān…zài…","desc":"Dipakai untuk menyatakan urutan kegiatan.","formula":"先 + Kegiatan 1，再 + Kegiatan 2","examples":[{"hz":"我先洗手，再吃饭。","py":"Wǒ xiān xǐ shǒu，zài chī fàn.","id":"Saya mencuci tangan dulu, lalu makan."},{"hz":"我们先买票，再进去。","py":"Wǒ men xiān mǎi piào，zài jìn qù.","id":"Kami membeli tiket dulu, lalu masuk."}]},{"hsk":3,"title":"对…感兴趣… duì…gǎn xìng qù…","hanzi":"对…感兴趣…","pinyin":"…… duì…gǎn xìng qù…","desc":"Dipakai untuk menyatakan tertarik pada sesuatu.","formula":"Subjek + 对 + Objek + 感兴趣","examples":[{"hz":"我对中文很感兴趣。","py":"Wǒ duì Zhōng wén hěn gǎn xìng qù.","id":"Saya sangat tertarik pada bahasa Mandarin."},{"hz":"他对音乐感兴趣。","py":"Tā duì yīn yuè gǎn xìng qù.","id":"Dia tertarik pada musik."}]},{"hsk":3,"title":"对…来说… duì…lái shuō…","hanzi":"对…来说…","pinyin":"…… duì…lái shuō…","desc":"Dipakai untuk menyatakan menurut atau bagi seseorang.","formula":"对 + Seseorang + 来说，Kalimat","examples":[{"hz":"对我来说，中文很有意思。","py":"Duì wǒ lái shuō，Zhōng wén hěn yǒu yì si.","id":"Bagi saya, bahasa Mandarin sangat menarik."},{"hz":"对孩子来说，睡觉很重要。","py":"Duì hái zi lái shuō，shuì jiào hěn zhòng yào.","id":"Bagi anak-anak, tidur sangat penting."}]},{"hsk":3,"title":"除了…都… chú le…dōu…","hanzi":"除了…都…","pinyin":"…… chú le…dōu…","desc":"Dipakai untuk menyatakan kecuali…semuanya…","formula":"除了 + A，其他 + 都 + …","examples":[{"hz":"除了他，我们都来了。","py":"Chú le tā，wǒ men dōu lái le.","id":"Selain dia, kami semua datang."},{"hz":"除了中文，我都会。","py":"Chú le Zhōng wén，wǒ dōu huì.","id":"Selain bahasa Mandarin, saya bisa semuanya."}]},{"hsk":3,"title":"还是 hái shi","hanzi":"还是","pinyin":"hái shi","desc":"Dipakai untuk menyatakan pilihan “atau” dalam kalimat tanya.","formula":"A + 还是 + B？","examples":[{"hz":"你喝茶还是咖啡？","py":"Nǐ hē chá hái shi kā fēi?","id":"Kamu minum teh atau kopi?"},{"hz":"今天坐公共汽车还是坐地铁？","py":"Jīn tiān zuò gōng gòng qì chē hái shi zuò dì tiě?","id":"Hari ini naik bus atau naik MRT?"}]},{"hsk":3,"title":"或者 huò zhě","hanzi":"或者","pinyin":"huò zhě","desc":"Dipakai untuk menyatakan pilihan atau dalam kalimat pernyataan.","formula":"A 或者 B","examples":[{"hz":"你可以坐公共汽车或者地铁。","py":"Nǐ kě yǐ zuò gōng gòng qì chē huò zhě dì tiě.","id":"Kamu boleh naik bus atau MRT."},{"hz":"我想喝茶或者咖啡。","py":"Wǒ xiǎng hē chá huò zhě kā fēi.","id":"Saya ingin minum teh atau kopi."}]},{"hsk":3,"title":"才 cái","hanzi":"才","pinyin":"cái","desc":"Dipakai untuk menyatakan sesuatu baru terjadi lebih lambat dari yang diharapkan.","formula":"Subjek + 才 + Kata Kerja","examples":[{"hz":"他九点才来。","py":"Tā jiǔ diǎn cái lái.","id":"Dia baru datang pukul sembilan."},{"hz":"我昨天才知道。","py":"Wǒ zuó tiān cái zhī dao.","id":"Saya baru mengetahuinya kemarin."}]},{"hsk":3,"title":"就 jiù","hanzi":"就","pinyin":"jiù","desc":"Dipakai untuk menyatakan sesuatu terjadi lebih cepat, langsung, atau lebih awal dari yang diharapkan.","formula":"Subjek + 就 + Kata Kerja","examples":[{"hz":"我七点就到了。","py":"Wǒ qī diǎn jiù dào le.","id":"Saya sudah sampai pukul tujuh."},{"hz":"他一听就明白了。","py":"Tā yì tīng jiù míng bai le.","id":"Begitu mendengar, dia langsung mengerti."}]},{"hsk":3,"title":"一共 yí gòng","hanzi":"一共","pinyin":"yí gòng","desc":"Dipakai untuk menyatakan jumlah keseluruhan atau total.","formula":"一共 + Jumlah","examples":[{"hz":"我们一共有二十个人。","py":"Wǒ men yí gòng yǒu èr shí gè rén.","id":"Kami berjumlah dua puluh orang."},{"hz":"这些书一共一百块钱。","py":"Zhè xiē shū yí gòng yì bǎi kuài qián.","id":"Semua buku ini total harganya seratus yuan."}]},{"hsk":3,"title":"以前…以后… yǐ qián…yǐ hòu…","hanzi":"以前…以后…","pinyin":"…… yǐ qián…yǐ hòu…","desc":"Dipakai untuk menyatakan waktu sebelum dan sesudah suatu kejadian.","formula":"Kata Kerja + 以前 = sebelum melakukan","examples":[{"hz":"吃饭以前，请洗手。","py":"Chī fàn yǐ qián，qǐng xǐ shǒu.","id":"Sebelum makan, tolong cuci tangan."},{"hz":"下课以后，我们去吃饭。","py":"Xià kè yǐ hòu，wǒ men qù chī fàn.","id":"Setelah kelas selesai, kami pergi makan."}]},{"hsk":4,"title":"并且 bìng qiě","hanzi":"并且","pinyin":"bìng qiě","desc":"Dipakai untuk menyatakan tambahan informasi, berarti “dan juga”, “selain itu”, “bahkan juga”.","formula":"Kalimat 1，并且 + Kalimat 2","examples":[{"hz":"他会说中文，并且会说英文。","py":"Tā huì shuō Zhōng wén, bìng qiě huì shuō Yīng wén.","id":"Dia bisa berbicara bahasa Mandarin dan juga bahasa Inggris."},{"hz":"她很认真，并且很努力。","py":"Tā hěn rèn zhēn, bìng qiě hěn nǔ lì.","id":"Dia sangat serius dan juga sangat rajin."}]},{"hsk":4,"title":"不管…都… bù guǎn…dōu…","hanzi":"不管…都…","pinyin":"…… bù guǎn…dōu…","desc":"Dipakai untuk menyatakan tidak peduli apa pun kondisinya, hasilnya tetap sama.","formula":"不管 + Kondisi，都 + Hasil","examples":[{"hz":"不管天气怎么样，我都去跑步。","py":"Bù guǎn tiān qì zěn me yàng, wǒ dōu qù pǎo bù.","id":"Apa pun cuacanya, saya tetap pergi berlari."},{"hz":"不管多忙，他都陪家人吃饭。","py":"Bù guǎn duō máng, tā dōu péi jiā rén chī fàn.","id":"Seberapa sibuk pun dia, dia tetap makan bersama keluarganya."}]},{"hsk":4,"title":"不过 bú guò","hanzi":"不过","pinyin":"bú guò","desc":"Dipakai untuk menyatakan pertentangan ringan, berarti “tetapi” / “namun”.","formula":"Kalimat 1，不过 + Kalimat 2","examples":[{"hz":"我想去，不过今天没时间。","py":"Wǒ xiǎng qù, bú guò jīn tiān méi shí jiān.","id":"Saya ingin pergi, tetapi hari ini tidak ada waktu."},{"hz":"这个菜很好吃，不过有一点辣。","py":"Zhè gè cài hěn hǎo chī, bú guò yǒu yì diǎn là.","id":"Makanan ini enak, tetapi agak pedas."}]},{"hsk":4,"title":"不仅…而且… bù jǐn…ér qiě…","hanzi":"不仅…而且…","pinyin":"…… bù jǐn…ér qiě…","desc":"Dipakai untuk menyatakan tidak hanya…, tetapi juga…","formula":"不仅 + A，而且 + B","examples":[{"hz":"他不仅会中文，而且会日文。","py":"Tā bù jǐn huì Zhōng wén, ér qiě huì Rì wén.","id":"Dia tidak hanya bisa bahasa Mandarin, tetapi juga bahasa Jepang."},{"hz":"这里不仅安静，而且很干净。","py":"Zhè lǐ bù jǐn ān jìng, ér qiě hěn gān jìng.","id":"Tempat ini tidak hanya tenang, tetapi juga sangat bersih."}]},{"hsk":4,"title":"否则 fǒu zé","hanzi":"否则","pinyin":"fǒu zé","desc":"Dipakai untuk menyatakan jika tidak, maka akan terjadi akibat tertentu.","formula":"Kalimat 1，否则 + Kalimat 2","examples":[{"hz":"快一点，否则会迟到。","py":"Kuài yì diǎn, fǒu zé huì chí dào.","id":"Cepatlah, kalau tidak akan terlambat."},{"hz":"你要多休息，否则会生病。","py":"Nǐ yào duō xiū xi, fǒu zé huì shēng bìng.","id":"Kamu harus banyak istirahat, kalau tidak akan sakit."}]},{"hsk":4,"title":"既然…就… jì rán…jiù…","hanzi":"既然…就…","pinyin":"…… jì rán…jiù…","desc":"Dipakai untuk menyatakan karena keadaannya sudah demikian, maka sebaiknya melakukan sesuatu.","formula":"既然 + Fakta，就 + Hasil","examples":[{"hz":"既然来了，就进去吧。","py":"Jì rán lái le, jiù jìn qù ba.","id":"Karena sudah datang, masuk saja."},{"hz":"既然知道了，就告诉大家。","py":"Jì rán zhī dao le, jiù gào su dà jiā.","id":"Karena sudah tahu, beri tahu semua orang."}]},{"hsk":4,"title":"即使…也… jí shǐ…yě…","hanzi":"即使…也…","pinyin":"…… jí shǐ…yě…","desc":"Dipakai untuk menyatakan sekalipun…, tetap…","formula":"即使 + Kondisi，也 + Hasil","examples":[{"hz":"即使很忙，我也会帮助你。","py":"Jí shǐ hěn máng, wǒ yě huì bāng zhù nǐ.","id":"Sekalipun sibuk, saya tetap akan membantumu."},{"hz":"即使下雨，他也去上班。","py":"Jí shǐ xià yǔ, tā yě qù shàng bān.","id":"Sekalipun hujan, dia tetap pergi bekerja."}]},{"hsk":4,"title":"可是 kě shì","hanzi":"可是","pinyin":"kě shì","desc":"Dipakai untuk menyatakan pertentangan atau kontras (tetapi/namun).","formula":"Kalimat 1，可是 + Kalimat 2","examples":[{"hz":"我很想去，可是今天没空。","py":"Wǒ hěn xiǎng qù, kě shì jīn tiān méi kòng.","id":"Saya sangat ingin pergi, tetapi hari ini tidak ada waktu."},{"hz":"他很努力，可是考试没通过。","py":"Tā hěn nǔ lì, kě shì kǎo shì méi tōng guò.","id":"Dia sangat rajin, tetapi tidak lulus ujian."}]},{"hsk":4,"title":"另外 lìng wài","hanzi":"另外","pinyin":"lìng wài","desc":"Dipakai untuk menambahkan informasi lain atau hal lain (selain itu).","formula":"Kalimat 1 + 另外 + Kalimat 2","examples":[{"hz":"我买了苹果，另外还买了香蕉。","py":"Wǒ mǎi le píng guǒ, lìng wài hái mǎi le xiāng jiāo.","id":"Saya membeli apel, selain itu juga membeli pisang."},{"hz":"今天我要开会，另外还要见客户。","py":"Jīn tiān wǒ yào kāi huì, lìng wài hái yào jiàn kè hù.","id":"Hari ini saya harus rapat, selain itu juga harus bertemu pelanggan."}]},{"hsk":4,"title":"然而 rán ér","hanzi":"然而","pinyin":"rán ér","desc":"Dipakai untuk menyatakan pertentangan yang lebih formal (namun).","formula":"Kalimat 1 + 然而 + Kalimat 2","examples":[{"hz":"他准备得很充分，然而还是失败了。","py":"Tā zhǔn bèi de hěn chōng fèn, rán ér hái shì shī bài le.","id":"Dia sudah mempersiapkan diri dengan sangat baik, namun tetap gagal."},{"hz":"天气很好，然而他不想出去。","py":"Tiān qì hěn hǎo, rán ér tā bù xiǎng chū qù.","id":"Cuacanya bagus, namun dia tidak ingin keluar."}]},{"hsk":4,"title":"甚至 shèn zhì","hanzi":"甚至","pinyin":"shèn zhì","desc":"Dipakai untuk menyatakan bahkan, untuk menunjukkan sesuatu yang lebih ekstrem atau di luar dugaan.","formula":"…甚至 + Kalimat/Kata Kerja/Kata Benda/Kata Sifat","examples":[{"hz":"他会说中文、英文，甚至日文。","py":"Tā huì shuō Zhōng wén, Yīng wén, shèn zhì Rì wén.","id":"Dia bisa berbahasa Mandarin, Inggris, bahkan Jepang."},{"hz":"他太忙了，甚至没时间吃饭。","py":"Tā tài máng le, shèn zhì méi shí jiān chī fàn.","id":"Dia sangat sibuk, bahkan tidak punya waktu untuk makan."}]},{"hsk":4,"title":"同时 tóng shí","hanzi":"同时","pinyin":"tóng shí","desc":"Dipakai untuk menyatakan pada saat yang sama atau sementara itu.","formula":"Kalimat 1，同时 + Kalimat 2","examples":[{"hz":"他一边工作，同时学习中文。","py":"Tā yì biān gōng zuò, tóng shí xué xí Zhōng wén.","id":"Dia bekerja sambil belajar bahasa Mandarin."},{"hz":"请注意安全，同时保护环境。","py":"Qǐng zhù yì ān quán, tóng shí bǎo hù huán jìng.","id":"Harap perhatikan keselamatan, sekaligus lindungi lingkungan."}]},{"hsk":4,"title":"无论…都… wú lùn…dōu…","hanzi":"无论…都…","pinyin":"…… wú lùn…dōu…","desc":"Dipakai untuk menyatakan apa pun keadaannya, hasilnya tetap sama.","formula":"无论 + Kondisi，都 + Hasil","examples":[{"hz":"无论多忙，我都会帮助你。","py":"Wú lùn duō máng, wǒ dōu huì bāng zhù nǐ.","id":"Seberapa sibuk pun, saya akan tetap membantumu."},{"hz":"无论天气怎么样，我们都去。","py":"Wú lùn tiān qì zěn me yàng, wǒ men dōu qù.","id":"Apa pun cuacanya, kami tetap pergi."}]},{"hsk":4,"title":"相反 xiāng fǎn","hanzi":"相反","pinyin":"xiāng fǎn","desc":"Dipakai untuk menyatakan sebaliknya atau kebalikannya.","formula":"Kalimat 1 + 相反，Kalimat 2","examples":[{"hz":"他没有生气，相反，他还笑了。","py":"Tā méi yǒu shēng qì, xiāng fǎn, tā hái xiào le.","id":"Dia tidak marah, sebaliknya dia malah tersenyum."},{"hz":"我不觉得难，相反，我觉得很简单。","py":"Wǒ bù jué de nán, xiāng fǎn, wǒ jué de hěn jiǎn dān.","id":"Saya tidak merasa sulit, sebaliknya saya merasa sangat mudah."}]},{"hsk":4,"title":"要是…就… yào shi…jiù…","hanzi":"要是…就…","pinyin":"…… yào shi…jiù…","desc":"Dipakai untuk menyatakan pengandaian (kalau…maka…).","formula":"要是 + Kondisi，就 + Hasil","examples":[{"hz":"要是有时间，我就去。","py":"Yào shi yǒu shí jiān, wǒ jiù qù.","id":"Kalau ada waktu, saya akan pergi."},{"hz":"要是下雨，我们就不去了。","py":"Yào shi xià yǔ, wǒ men jiù bù qù le.","id":"Kalau hujan, kami tidak jadi pergi."}]},{"hsk":4,"title":"由于 yóu yú","hanzi":"由于","pinyin":"yóu yú","desc":"Dipakai untuk menyatakan penyebab atau alasan, berarti “karena” atau “disebabkan oleh”.","formula":"由于 + Penyebab，Hasil","examples":[{"hz":"由于天气不好，飞机晚点了。","py":"Yóu yú tiān qì bù hǎo, fēi jī wǎn diǎn le.","id":"Karena cuaca buruk, pesawat terlambat."},{"hz":"由于生病，他没来上课。","py":"Yóu yú shēng bìng, tā méi lái shàng kè.","id":"Karena sakit, dia tidak datang ke kelas."}]},{"hsk":4,"title":"于是 yú shì","hanzi":"于是","pinyin":"yú shì","desc":"Dipakai untuk menyatakan akibat yang terjadi setelah suatu peristiwa, berarti “kemudian” atau “akhirnya”.","formula":"Kalimat 1，于是 + Kalimat 2","examples":[{"hz":"我忘了带钱包，于是回家拿。","py":"Wǒ wàng le dài qián bāo, yú shì huí jiā ná.","id":"Saya lupa membawa dompet, jadi saya pulang untuk mengambilnya."},{"hz":"他觉得很累，于是早点睡觉。","py":"Tā jué de hěn lèi, yú shì zǎo diǎn shuì jiào.","id":"Dia merasa sangat lelah, jadi dia tidur lebih awal."}]},{"hsk":4,"title":"只要…就… zhǐ yào…jiù…","hanzi":"只要…就…","pinyin":"…… zhǐ yào…jiù…","desc":"Dipakai untuk menyatakan syarat, berarti “asalkan…maka…”.","formula":"只要 + Syarat，就 + Hasil","examples":[{"hz":"只要努力，就会成功。","py":"Zhǐ yào nǔ lì, jiù huì chéng gōng.","id":"Asalkan berusaha, maka akan berhasil."},{"hz":"只要你来，我就很高兴。","py":"Zhǐ yào nǐ lái, wǒ jiù hěn gāo xìng.","id":"Asalkan kamu datang, saya akan sangat senang."}]},{"hsk":4,"title":"难道…? nán dào…?","hanzi":"难道…?…?","pinyin":"…? nán dào…","desc":"Dipakai untuk menyatakan pertanyaan retoris yang menunjukkan rasa heran, tidak percaya, atau menegaskan sesuatu.","formula":"难道 + Kalimat + 吗？","examples":[{"hz":"难道你不知道吗？","py":"Nán dào nǐ bù zhī dao ma?","id":"Masa kamu tidak tahu?"},{"hz":"难道他已经走了吗？","py":"Nán dào tā yǐ jīng zǒu le ma?","id":"Masa dia sudah pergi?"}]},{"hsk":4,"title":"连…都… lián…dōu…","hanzi":"连…都…","pinyin":"…… lián…dōu…","desc":"Dipakai untuk menyatakan bahkan…pun…, untuk menekankan sesuatu yang di luar dugaan.","formula":"连 + Objek/Subjek，都 + Kalimat","examples":[{"hz":"连老师都不知道。","py":"Lián lǎo shī dōu bù zhī dao.","id":"Bahkan guru pun tidak tahu."},{"hz":"连小孩子都会说。","py":"Lián xiǎo hái zi dōu huì shuō.","id":"Bahkan anak kecil pun bisa mengatakannya."}]},{"hsk":4,"title":"下来 xià lái","hanzi":"下来","pinyin":"xià lái","desc":"Dipakai untuk menyatakan gerakan ke bawah menuju pembicara atau keadaan yang menjadi tetap.","formula":"Kata Kerja + 下来","examples":[{"hz":"请坐下来。","py":"Qǐng zuò xià lái.","id":"Silakan duduk."},{"hz":"他停下来休息。","py":"Tā tíng xià lái xiū xi.","id":"Dia berhenti untuk beristirahat."}]},{"hsk":4,"title":"下去 xià qù","hanzi":"下去","pinyin":"xià qù","desc":"Dipakai untuk menyatakan melanjutkan suatu tindakan atau gerakan ke bawah menjauhi pembicara.","formula":"Kata Kerja + 下去","examples":[{"hz":"请继续说下去。","py":"Qǐng jì xù shuō xià qù.","id":"Silakan lanjutkan berbicara."},{"hz":"这样做下去是不行的。","py":"Zhè yàng zuò xià qù shì bù xíng de.","id":"Kalau terus seperti ini, tidak akan berhasil."}]},{"hsk":4,"title":"除了…以外… chú le…yǐ wài…","hanzi":"除了…以外…","pinyin":"…… chú le…yǐ wài…","desc":"Dipakai untuk menyatakan selain…, baik dengan arti “juga” maupun “kecuali”, tergantung konteks.","formula":"除了 + A + 以外，还/也 + B","examples":[{"hz":"除了中文以外，我还会英文。","py":"Chú le Zhōng wén yǐ wài, wǒ hái huì Yīng wén.","id":"Selain bahasa Mandarin, saya juga bisa bahasa Inggris."},{"hz":"除了他以外，大家都到了。","py":"Chú le tā yǐ wài, dà jiā dōu dào le.","id":"Selain dia, semua orang sudah datang."}]},{"hsk":4,"title":"一方面…另一方面… yì fāng miàn…lìng yì fāng miàn…","hanzi":"一方面…另一方面…","pinyin":"…… yì fāng miàn…lìng yì fāng miàn…","desc":"Dipakai untuk menyatakan dua sisi atau dua aspek dari suatu hal.","formula":"一方面 + A，另一方面 + B","examples":[{"hz":"一方面我想工作，另一方面我想继续学习。","py":"Yì fāng miàn wǒ xiǎng gōng zuò, lìng yì fāng miàn wǒ xiǎng jì xù xué xí.","id":"Di satu sisi saya ingin bekerja, di sisi lain saya ingin melanjutkan belajar."},{"hz":"一方面我很想去，另一方面我没有时间。","py":"Yì fāng miàn wǒ hěn xiǎng qù, lìng yì fāng miàn wǒ méi yǒu shí jiān.","id":"Di satu sisi saya sangat ingin pergi, di sisi lain saya tidak punya waktu."}]},{"hsk":4,"title":"因此 yīn cǐ","hanzi":"因此","pinyin":"yīn cǐ","desc":"Dipakai untuk menyatakan akibat atau kesimpulan, berarti “oleh karena itu”.","formula":"Penyebab + 因此 + Hasil","examples":[{"hz":"今天下大雨，因此比赛取消了。","py":"Jīn tiān xià dà yǔ, yīn cǐ bǐ sài qǔ xiāo le.","id":"Hari ini hujan deras, oleh karena itu pertandingan dibatalkan."},{"hz":"他努力学习，因此成绩很好。","py":"Tā nǔ lì xué xí, yīn cǐ chéng jì hěn hǎo.","id":"Dia belajar dengan giat, oleh karena itu nilainya sangat baik."}]},{"hsk":5,"title":"与其…不如… yǔ qí…bù rú…","hanzi":"与其…不如…","pinyin":"yǔ qí…bù rú…","desc":"Dipakai untuk menyatakan bahwa daripada memilih A, lebih baik memilih B.","formula":"与其 + A，不如 + B","examples":[{"hz":"与其坐公共汽车，不如坐地铁。","py":"Yǔ qí zuò gōng gòng qì chē, bù rú zuò dì tiě.","id":"Daripada naik bus, lebih baik naik metro."},{"hz":"与其担心，不如马上开始。","py":"Yǔ qí dān xīn, bù rú mǎ shàng kāi shǐ.","id":"Daripada khawatir, lebih baik segera mulai."}]},{"hsk":5,"title":"宁可…也… nìng kě…yě…","hanzi":"宁可…也…","pinyin":"nìng kě…yě…","desc":"Dipakai untuk menyatakan lebih memilih melakukan sesuatu daripada melakukan hal lain.","formula":"宁可 + A，也 + B","examples":[{"hz":"我宁可走路，也不坐出租车。","py":"Wǒ nìng kě zǒu lù, yě bù zuò chū zū chē.","id":"Saya lebih memilih berjalan kaki daripada naik taksi."},{"hz":"他宁可自己做，也不麻烦别人。","py":"Tā nìng kě zì jǐ zuò, yě bù má fan bié rén.","id":"Dia lebih memilih mengerjakannya sendiri daripada merepotkan orang lain."}]},{"hsk":5,"title":"既…又… jì…yòu…","hanzi":"既…又…","pinyin":"jì…yòu…","desc":"Dipakai untuk menyatakan bahwa seseorang atau sesuatu memiliki dua sifat atau keadaan sekaligus.","formula":"既 + Sifat/Kata Kerja，又 + Sifat/Kata Kerja","examples":[{"hz":"她既漂亮，又善良。","py":"Tā jì piào liang, yòu shàn liáng.","id":"Dia cantik dan juga baik hati."},{"hz":"这个地方既安静，又方便。","py":"Zhè gè dì fang jì ān jìng, yòu fāng biàn.","id":"Tempat ini tenang sekaligus nyaman."}]},{"hsk":5,"title":"不但…反而… bù dàn…fǎn ér…","hanzi":"不但…反而…","pinyin":"bù dàn…fǎn ér…","desc":"Dipakai untuk menyatakan bahwa hasil yang terjadi justru berlawanan dengan yang diharapkan.","formula":"不但 + Tidak Terjadi，反而 + Hasil yang Berlawanan","examples":[{"hz":"他不但没生气，反而笑了。","py":"Tā bù dàn méi shēng qì, fǎn ér xiào le.","id":"Dia bukan saja tidak marah, malah tersenyum."},{"hz":"吃了药以后，他不但没好，反而更严重了。","py":"Chī le yào yǐ hòu, tā bù dàn méi hǎo, fǎn ér gèng yán zhòng le.","id":"Setelah minum obat, dia bukannya membaik, malah menjadi lebih parah."}]},{"hsk":5,"title":"即便…也… jí biàn…yě…","hanzi":"即便…也…","pinyin":"jí biàn…yě…","desc":"Dipakai untuk menyatakan sekalipun…, tetap…","formula":"即便 + Kondisi，也 + Hasil","examples":[{"hz":"即便失败了，也不要放弃。","py":"Jí biàn shī bài le, yě bú yào fàng qì.","id":"Sekalipun gagal, jangan menyerah."},{"hz":"即便很远，我们也会去。","py":"Jí biàn hěn yuǎn, wǒ men yě huì qù.","id":"Sekalipun sangat jauh, kami tetap akan pergi."}]},{"hsk":5,"title":"何况 hé kuàng","hanzi":"何况","pinyin":"hé kuàng","desc":"Dipakai untuk menyatakan apalagi, untuk memperkuat alasan.","formula":"Kalimat 1，何况 + Kalimat 2","examples":[{"hz":"他连中文都会说，何况英文。","py":"Tā lián Zhōng wén dōu huì shuō, hé kuàng Yīng wén.","id":"Dia bahkan bisa bahasa Mandarin, apalagi bahasa Inggris."},{"hz":"大人都觉得冷，何况孩子。","py":"Dà rén dōu jué de lěng, hé kuàng hái zi.","id":"Orang dewasa saja merasa dingin, apalagi anak-anak."}]},{"hsk":5,"title":"况且 kuàng qiě","hanzi":"况且","pinyin":"kuàng qiě","desc":"Dipakai untuk menambahkan alasan yang lebih kuat, berarti terlebih lagi.","formula":"Kalimat 1，况且 + Kalimat 2","examples":[{"hz":"今天太晚了，况且外面还下着雨。","py":"Jīn tiān tài wǎn le, kuàng qiě wài miàn hái xià zhe yǔ.","id":"Hari sudah terlalu malam, terlebih lagi di luar masih hujan."},{"hz":"他已经很忙了，况且身体也不舒服。","py":"Tā yǐ jīng hěn máng le, kuàng qiě shēn tǐ yě bù shū fu.","id":"Dia sudah sangat sibuk, terlebih lagi badannya juga kurang sehat."}]},{"hsk":5,"title":"以免 yǐ miǎn","hanzi":"以免","pinyin":"yǐ miǎn","desc":"Dipakai untuk menyatakan tujuan agar tidak terjadi sesuatu.","formula":"Kalimat，以免 + Akibat yang Tidak Diinginkan","examples":[{"hz":"请早点出门，以免迟到。","py":"Qǐng zǎo diǎn chū mén, yǐ miǎn chí dào.","id":"Berangkatlah lebih awal agar tidak terlambat."},{"hz":"多喝水，以免感冒。","py":"Duō hē shuǐ, yǐ miǎn gǎn mào.","id":"Minumlah lebih banyak air agar tidak masuk angin."}]},{"hsk":5,"title":"以便 yǐ biàn","hanzi":"以便","pinyin":"yǐ biàn","desc":"Dipakai untuk menyatakan tujuan, berarti agar atau supaya.","formula":"Kalimat，以便 + Tujuan","examples":[{"hz":"请写下来，以便以后查看。","py":"Qǐng xiě xià lái, yǐ biàn yǐ hòu chá kàn.","id":"Tolong tuliskan agar nanti bisa dilihat kembali."},{"hz":"我早点睡觉，以便明天有精神。","py":"Wǒ zǎo diǎn shuì jiào, yǐ biàn míng tiān yǒu jīng shén.","id":"Saya tidur lebih awal agar besok lebih segar."}]},{"hsk":5,"title":"只有…才… zhǐ yǒu…cái…","hanzi":"只有…才…","pinyin":"zhǐ yǒu…cái…","desc":"Dipakai untuk menyatakan bahwa hanya jika syarat terpenuhi, hasil dapat terjadi.","formula":"只有 + Syarat，才 + Hasil","examples":[{"hz":"只有努力，才能成功。","py":"Zhǐ yǒu nǔ lì, cái néng chéng gōng.","id":"Hanya dengan bekerja keras, barulah bisa berhasil."},{"hz":"只有认真学习，才会进步。","py":"Zhǐ yǒu rèn zhēn xué xí, cái huì jìn bù.","id":"Hanya jika belajar dengan sungguh-sungguh, barulah bisa berkembang."}]},{"hsk":5,"title":"由…来看… yóu…lái kàn…","hanzi":"由…来看…","pinyin":"yóu…lái kàn…","desc":"Dipakai untuk menyatakan jika dilihat dari suatu aspek.","formula":"由 + Aspek + 来看，Kalimat","examples":[{"hz":"由成绩来看，他进步了很多。","py":"Yóu chéng jì lái kàn, tā jìn bù le hěn duō.","id":"Dilihat dari nilainya, dia mengalami banyak kemajuan."},{"hz":"由现在的情况来看，我们应该早点出发。","py":"Yóu xiàn zài de qíng kuàng lái kàn, wǒ men yīng gāi zǎo diǎn chū fā.","id":"Dilihat dari keadaan saat ini, kita sebaiknya berangkat lebih awal."}]},{"hsk":5,"title":"随着 suí zhe","hanzi":"随着","pinyin":"suí zhe","desc":"Dipakai untuk menyatakan seiring dengan perubahan atau perkembangan sesuatu.","formula":"随着 + Perubahan，Kalimat","examples":[{"hz":"随着年龄的增长，他越来越成熟。","py":"Suí zhe nián líng de zēng zhǎng, tā yuè lái yuè chéng shú.","id":"Seiring bertambahnya usia, dia semakin dewasa."},{"hz":"随着科技的发展，人们的生活越来越方便。","py":"Suí zhe kē jì de fā zhǎn, rén men de shēng huó yuè lái yuè fāng biàn.","id":"Seiring perkembangan teknologi, kehidupan manusia menjadi semakin mudah."}]},{"hsk":5,"title":"对于 duì yú","hanzi":"对于","pinyin":"duì yú","desc":"Dipakai untuk menyatakan terhadap atau mengenai suatu hal.","formula":"对于 + Objek，Kalimat","examples":[{"hz":"对于这个问题，我有不同的看法。","py":"Duì yú zhè gè wèn tí, wǒ yǒu bù tóng de kàn fǎ.","id":"Mengenai masalah ini, saya memiliki pendapat yang berbeda."},{"hz":"老师对于学生很有耐心。","py":"Lǎo shī duì yú xué shēng hěn yǒu nài xīn.","id":"Guru sangat sabar terhadap para siswa."}]},{"hsk":5,"title":"并非…而是… bìng fēi…ér shì…","hanzi":"并非…而是…","pinyin":"bìng fēi…ér shì…","desc":"Dipakai untuk menyatakan bukan…, melainkan…, biasanya dalam situasi yang lebih formal.","formula":"并非 + A，而是 + B","examples":[{"hz":"他并非不想去，而是没有时间。","py":"Tā bìng fēi bù xiǎng qù, ér shì méi yǒu shí jiān.","id":"Bukannya dia tidak ingin pergi, melainkan dia tidak punya waktu."},{"hz":"成功并非靠运气，而是靠努力。","py":"Chéng gōng bìng fēi kào yùn qi, ér shì kào nǔ lì.","id":"Keberhasilan bukan bergantung pada keberuntungan, melainkan pada kerja keras."}]},{"hsk":5,"title":"由此可见 yóu cǐ kě jiàn","hanzi":"由此可见","pinyin":"yóu cǐ kě jiàn","desc":"Dipakai untuk menyatakan kesimpulan berdasarkan fakta yang telah dijelaskan sebelumnya.","formula":"Fakta + 由此可见 + Kesimpulan","examples":[{"hz":"他每天坚持学习，成绩一直提高。由此可见，努力很重要。","py":"Tā měi tiān jiān chí xué xí, chéng jì yì zhí tí gāo. Yóu cǐ kě jiàn, nǔ lì hěn zhòng yào.","id":"Dia belajar dengan tekun setiap hari dan nilainya terus meningkat. Dari sini dapat disimpulkan bahwa kerja keras sangat penting."},{"hz":"很多人开始使用新能源汽车。由此可见，环保越来越受到重视。","py":"Hěn duō rén kāi shǐ shǐ yòng xīn néng yuán qì chē. Yóu cǐ kě jiàn, huán bǎo yuè lái yuè shòu dào zhòng shì.","id":"Semakin banyak orang mulai menggunakan kendaraan energi baru. Dari sini dapat disimpulkan bahwa perlindungan lingkungan semakin mendapat perhatian."}]},{"hsk":5,"title":"总之 zǒng zhī","hanzi":"总之","pinyin":"zǒng zhī","desc":"Dipakai untuk menyatakan kesimpulan atau ringkasan.","formula":"Penjelasan + 总之 + Kesimpulan","examples":[{"hz":"这次旅行很开心，也学到了很多东西。总之，这是一次难忘的旅行。","py":"Zhè cì lǚ yóu hěn kāi xīn, yě xué dào le hěn duō dōng xi. Zǒng zhī, zhè shì yí cì nán wàng de lǚ yóu.","id":"Perjalanan kali ini sangat menyenangkan dan saya belajar banyak hal. Singkatnya, ini adalah perjalanan yang tak terlupakan."},{"hz":"他工作认真，也很负责。总之，他是一位优秀的员工。","py":"Tā gōng zuò rèn zhēn, yě hěn fù zé. Zǒng zhī, tā shì yí wèi yōu xiù de yuán gōng.","id":"Dia bekerja dengan sungguh-sungguh dan sangat bertanggung jawab. Singkatnya, dia adalah karyawan yang luar biasa."}]},{"hsk":5,"title":"换句话说 huàn jù huà shuō","hanzi":"换句话说","pinyin":"huàn jù huà shuō","desc":"Dipakai untuk menyatakan penjelasan lain dengan kata-kata yang berbeda.","formula":"Kalimat + 换句话说 + Penjelasan","examples":[{"hz":"他不会来。换句话说，我们不用等他了。","py":"Tā bú huì lái. Huàn jù huà shuō, wǒ men bú yòng děng tā le.","id":"Dia tidak akan datang. Dengan kata lain, kita tidak perlu menunggunya lagi."},{"hz":"这份工作需要经验。换句话说，新人很难申请。","py":"Zhè fèn gōng zuò xū yào jīng yàn. Huàn jù huà shuō, xīn rén hěn nán shēn qǐng.","id":"Pekerjaan ini membutuhkan pengalaman. Dengan kata lain, pendatang baru akan sulit melamar."}]},{"hsk":5,"title":"换言之 huàn yán zhī","hanzi":"换言之","pinyin":"huàn yán zhī","desc":"Dipakai untuk menyatakan penjelasan ulang secara lebih formal, berarti “dengan kata lain”.","formula":"Kalimat + 换言之 + Penjelasan","examples":[{"hz":"他没有通过考试。换言之，他需要再参加一次考试。","py":"Tā méi yǒu tōng guò kǎo shì. Huàn yán zhī, tā xū yào zài cān jiā yí cì kǎo shì.","id":"Dia tidak lulus ujian. Dengan kata lain, dia perlu mengikuti ujian lagi."},{"hz":"这项计划失败了。换言之，我们要重新开始。","py":"Zhè xiàng jì huà shī bài le. Huàn yán zhī, wǒ men yào chóng xīn kāi shǐ.","id":"Rencana ini gagal. Dengan kata lain, kita harus memulai lagi."}]},{"hsk":5,"title":"以…来说… yǐ…lái shuō…","hanzi":"以…来说…","pinyin":"yǐ…lái shuō…","desc":"Dipakai untuk menyatakan jika dilihat dari suatu sudut pandang atau aspek.","formula":"以 + Aspek/Orang + 来说，Kalimat","examples":[{"hz":"以价格来说，这家饭店不贵。","py":"Yǐ jià gé lái shuō, zhè jiā fàn diàn bú guì.","id":"Dilihat dari harganya, restoran ini tidak mahal."},{"hz":"以我来说，我更喜欢住在小城市。","py":"Yǐ wǒ lái shuō, wǒ gèng xǐ huan zhù zài xiǎo chéng shì.","id":"Bagi saya, saya lebih suka tinggal di kota kecil."}]},{"hsk":6,"title":"姑且 gū qiě","hanzi":"姑且","pinyin":"gū qiě","desc":"Dipakai untuk menyatakan sementara, biasanya sebelum ada keputusan atau solusi yang lebih baik.","formula":"姑且 + Kata Kerja / Kalimat","examples":[{"hz":"这件事我们姑且不谈。","py":"Zhè jiàn shì wǒ men gū qiě bù tán.","id":"Masalah ini untuk sementara tidak kita bahas."},{"hz":"姑且相信他说的话吧。","py":"Gū qiě xiāng xìn tā shuō de huà ba.","id":"Untuk sementara, percayalah dulu pada apa yang dia katakan."}]},{"hsk":6,"title":"宁愿…也不… nìng yuàn…yě bù…","hanzi":"宁愿…也不…","pinyin":"nìng yuàn…yě bù…","desc":"Dipakai untuk menyatakan lebih memilih melakukan sesuatu daripada melakukan hal lain.","formula":"宁愿 + A，也不 + B","examples":[{"hz":"我宁愿走路，也不坐出租车。","py":"Wǒ nìng yuàn zǒu lù, yě bù zuò chū zū chē.","id":"Saya lebih memilih berjalan kaki daripada naik taksi."},{"hz":"他宁愿自己做，也不麻烦别人。","py":"Tā nìng yuàn zì jǐ zuò, yě bù má fan bié rén.","id":"Dia lebih memilih mengerjakannya sendiri daripada merepotkan orang lain."}]},{"hsk":6,"title":"纵然…也… zòng rán…yě…","hanzi":"纵然…也…","pinyin":"zòng rán…yě…","desc":"Dipakai untuk menyatakan sekalipun, biasanya dalam bahasa yang lebih formal daripada 即使.","formula":"纵然 + Kondisi，也 + Hasil","examples":[{"hz":"纵然失败了，也不要放弃。","py":"Zòng rán shī bài le, yě bú yào fàng qì.","id":"Sekalipun gagal, jangan menyerah."},{"hz":"纵然遇到困难，他也不会退缩。","py":"Zòng rán yù dào kùn nan, tā yě bú huì tuì suō.","id":"Sekalipun menghadapi kesulitan, dia tidak akan mundur."}]},{"hsk":6,"title":"以致 yǐ zhì","hanzi":"以致","pinyin":"yǐ zhì","desc":"Dipakai untuk menyatakan akibat, biasanya berakibat buruk.","formula":"Penyebab，以致 + Akibat","examples":[{"hz":"他太累了，以致生病了。","py":"Tā tài lèi le, yǐ zhì shēng bìng le.","id":"Dia terlalu lelah sehingga jatuh sakit."},{"hz":"昨天下大雨，以致很多航班取消了。","py":"Zuó tiān xià dà yǔ, yǐ zhì hěn duō háng bān qǔ xiāo le.","id":"Kemarin hujan deras sehingga banyak penerbangan dibatalkan."}]},{"hsk":6,"title":"从…角度来看… cóng…jiǎo dù lái kàn…","hanzi":"从…角度来看…","pinyin":"cóng…jiǎo dù lái kàn…","desc":"Dipakai untuk menyatakan jika dilihat dari sudut pandang tertentu.","formula":"从 + Aspek + 角度来看，Kalimat","examples":[{"hz":"从经济角度来看，这个计划很好。","py":"Cóng jīng jì jiǎo dù lái kàn, zhè gè jì huà hěn hǎo.","id":"Dilihat dari sudut pandang ekonomi, rencana ini sangat baik."},{"hz":"从学生的角度来看，这门课有一点难。","py":"Cóng xué shēng de jiǎo dù lái kàn, zhè mén kè yǒu yì diǎn nán.","id":"Dilihat dari sudut pandang siswa, mata kuliah ini agak sulit."}]},{"hsk":6,"title":"归根结底 guī gēn jié dǐ","hanzi":"归根结底","pinyin":"guī gēn jié dǐ","desc":"Dipakai untuk menyatakan pada akhirnya atau pada dasarnya setelah mempertimbangkan semua hal.","formula":"归根结底 + Kalimat","examples":[{"hz":"归根结底，努力才是最重要的。","py":"Guī gēn jié dǐ, nǔ lì cái shì zuì zhòng yào de.","id":"Pada akhirnya, kerja keraslah yang paling penting."},{"hz":"归根结底，健康比钱更重要。","py":"Guī gēn jié dǐ, jiàn kāng bǐ qián gèng zhòng yào.","id":"Pada akhirnya, kesehatan lebih penting daripada uang."}]},{"hsk":6,"title":"由此看来 yóu cǐ kàn lái","hanzi":"由此看来","pinyin":"yóu cǐ kàn lái","desc":"Dipakai untuk menyatakan kesimpulan berdasarkan fakta yang telah disebutkan.","formula":"Fakta。由此看来，Kesimpulan","examples":[{"hz":"他每天坚持学习，成绩越来越好。由此看来，坚持很重要。","py":"Tā měi tiān jiān chí xué xí, chéng jì yuè lái yuè hǎo. Yóu cǐ kàn lái, jiān chí hěn zhòng yào.","id":"Dia belajar setiap hari dan nilainya semakin baik. Dari sini dapat dilihat bahwa ketekunan sangat penting."},{"hz":"现在越来越多人学习中文。由此看来，中文越来越受欢迎。","py":"Xiàn zài yuè lái yuè duō rén xué xí Zhōng wén. Yóu cǐ kàn lái, Zhōng wén yuè lái yuè shòu huān yíng.","id":"Sekarang semakin banyak orang belajar bahasa Mandarin. Dari sini dapat dilihat bahwa bahasa Mandarin semakin populer."}]},{"hsk":6,"title":"可见 kě jiàn","hanzi":"可见","pinyin":"kě jiàn","desc":"Dipakai untuk menyatakan dapat dilihat bahwa atau jelas bahwa, biasanya digunakan untuk menyimpulkan suatu fakta.","formula":"Fakta，可见 + Kesimpulan","examples":[{"hz":"他每天坚持跑步，可见他很重视健康。","py":"Tā měi tiān jiān chí pǎo bù, kě jiàn tā hěn zhòng shì jiàn kāng.","id":"Dia berlari setiap hari. Jelas bahwa dia sangat mementingkan kesehatan."},{"hz":"这家饭店每天都有很多客人，可见这里的菜很好吃。","py":"Zhè jiā fàn diàn měi tiān dōu yǒu hěn duō kè rén, kě jiàn zhè lǐ de cài hěn hǎo chī.","id":"Restoran ini setiap hari memiliki banyak pelanggan. Dapat dilihat bahwa masakannya sangat enak."}]},{"hsk":6,"title":"与此同时 yǔ cǐ tóng shí","hanzi":"与此同时","pinyin":"yǔ cǐ tóng shí","desc":"Dipakai untuk menyatakan pada saat yang sama atau sementara itu, biasanya untuk menghubungkan dua kejadian yang berlangsung bersamaan.","formula":"Kalimat 1。与此同时，Kalimat 2","examples":[{"hz":"他努力学习。与此同时，他也坚持运动。","py":"Tā nǔ lì xué xí. Yǔ cǐ tóng shí, tā yě jiān chí yùn dòng.","id":"Dia belajar dengan giat. Pada saat yang sama, dia juga rutin berolahraga."},{"hz":"公司提高了工资。与此同时，也改善了工作环境。","py":"Gōng sī tí gāo le gōng zī. Yǔ cǐ tóng shí, yě gǎi shàn le gōng zuò huán jìng.","id":"Perusahaan menaikkan gaji. Pada saat yang sama, perusahaan juga memperbaiki lingkungan kerja."}]},{"hsk":6,"title":"总而言之 zǒng ér yán zhī","hanzi":"总而言之","pinyin":"zǒng ér yán zhī","desc":"Dipakai untuk menyatakan kesimpulan akhir dari beberapa penjelasan.","formula":"Penjelasan。总而言之，Kesimpulan","examples":[{"hz":"这次旅行很开心，也学到了很多东西。总而言之，这是一次难忘的旅行。","py":"Zhè cì lǚ yóu hěn kāi xīn, yě xué dào le hěn duō dōng xi. Zǒng ér yán zhī, zhè shì yí cì nán wàng de lǚ yóu.","id":"Perjalanan kali ini sangat menyenangkan dan saya belajar banyak hal. Singkatnya, ini adalah perjalanan yang tak terlupakan."},{"hz":"他工作认真，也很负责。总而言之，他是一位优秀的员工。","py":"Tā gōng zuò rèn zhēn, yě hěn fù zé. Zǒng ér yán zhī, tā shì yí wèi yōu xiù de yuán gōng.","id":"Dia bekerja dengan sungguh-sungguh dan bertanggung jawab. Singkatnya, dia adalah karyawan yang sangat baik."}]},{"hsk":6,"title":"非但…反而… fēi dàn…fǎn ér…","hanzi":"非但…反而…","pinyin":"fēi dàn…fǎn ér…","desc":"Dipakai untuk menyatakan bahwa hasil yang terjadi justru berkebalikan dengan yang diharapkan.","formula":"非但 + Tidak Terjadi，反而 + Hasil yang Berlawanan","examples":[{"hz":"他非但没有道歉，反而责怪别人。","py":"Tā fēi dàn méi yǒu dào qiàn, fǎn ér zé guài bié rén.","id":"Dia bukan saja tidak meminta maaf, malah menyalahkan orang lain."},{"hz":"吃了药以后，他非但没有好转，反而更严重了。","py":"Chī le yào yǐ hòu, tā fēi dàn méi yǒu hǎo zhuǎn, fǎn ér gèng yán zhòng le.","id":"Setelah minum obat, bukannya membaik, malah semakin parah."}]},{"hsk":6,"title":"无非 wú fēi","hanzi":"无非","pinyin":"wú fēi","desc":"Dipakai untuk menyatakan tidak lebih dari atau hanyalah, untuk menunjukkan bahwa sesuatu sebenarnya sederhana.","formula":"无非 + Kata Benda / Kalimat","examples":[{"hz":"这件事无非是个误会。","py":"Zhè jiàn shì wú fēi shì gè wù huì.","id":"Masalah ini tidak lebih dari sebuah kesalahpahaman."},{"hz":"他这么做，无非是想帮助大家。","py":"Tā zhè me zuò, wú fēi shì xiǎng bāng zhù dà jiā.","id":"Dia melakukan ini tidak lain hanya untuk membantu semua orang."}]},{"hsk":6,"title":"无疑 wú yí","hanzi":"无疑","pinyin":"wú yí","desc":"Dipakai untuk menyatakan tidak diragukan lagi.","formula":"无疑 + Kalimat","examples":[{"hz":"他无疑是我们班最优秀的学生。","py":"Tā wú yí shì wǒ men bān zuì yōu xiù de xué shēng.","id":"Dia tidak diragukan lagi adalah siswa terbaik di kelas kami."},{"hz":"这项技术无疑会改变我们的生活。","py":"Zhè xiàng jì shù wú yí huì gǎi biàn wǒ men de shēng huó.","id":"Teknologi ini tidak diragukan lagi akan mengubah kehidupan kita."}]},{"hsk":6,"title":"未必 wèi bì","hanzi":"未必","pinyin":"wèi bì","desc":"Dipakai untuk menyatakan belum tentu.","formula":"Subjek + 未必 + Kata Kerja / Kata Sifat","examples":[{"hz":"贵的东西未必最好。","py":"Guì de dōng xi wèi bì zuì hǎo.","id":"Barang yang mahal belum tentu yang terbaik."},{"hz":"他今天未必会来。","py":"Tā jīn tiān wèi bì huì lái.","id":"Hari ini dia belum tentu akan datang."}]},{"hsk":6,"title":"难免 nán miǎn","hanzi":"难免","pinyin":"nán miǎn","desc":"Dipakai untuk menyatakan bahwa sesuatu sulit dihindari.","formula":"Subjek + 难免 + Kata Kerja / Kalimat","examples":[{"hz":"刚开始学习，难免会犯错误。","py":"Gāng kāi shǐ xué xí, nán miǎn huì fàn cuò wù.","id":"Baru mulai belajar, sulit menghindari kesalahan."},{"hz":"工作太忙，难免会觉得累。","py":"Gōng zuò tài máng, nán miǎn huì jué de lèi.","id":"Pekerjaan yang terlalu sibuk membuat rasa lelah sulit dihindari."}]},{"hsk":6,"title":"不至于 bú zhì yú","hanzi":"不至于","pinyin":"bú zhì yú","desc":"Dipakai untuk menyatakan tidak sampai atau tidak sedemikian parah.","formula":"Subjek + 不至于 + Kata Kerja / Kalimat","examples":[{"hz":"这件事不至于这么严重。","py":"Zhè jiàn shì bú zhì yú zhè me yán zhòng.","id":"Masalah ini tidak sampai separah itu."},{"hz":"他只是迟到了，不至于被开除。","py":"Tā zhǐ shì chí dào le, bú zhì yú bèi kāi chú.","id":"Dia hanya terlambat, tidak sampai harus dipecat."}]},{"hsk":6,"title":"舍不得 shě bu de","hanzi":"舍不得","pinyin":"shě bu de","desc":"Dipakai untuk menyatakan tidak rela, tidak tega, atau sayang untuk melepaskan sesuatu.","formula":"Subjek + 舍不得 + Kata Kerja / Objek","examples":[{"hz":"我舍不得离开家人。","py":"Wǒ shě bu de lí kāi jiā rén.","id":"Saya tidak rela meninggalkan keluarga."},{"hz":"这本书很好，我舍不得送给别人。","py":"Zhè běn shū hěn hǎo, wǒ shě bu de sòng gěi bié rén.","id":"Buku ini sangat bagus, saya tidak tega memberikannya kepada orang lain."}]},{"hsk":6,"title":"怪不得 guài bu de","hanzi":"怪不得","pinyin":"guài bu de","desc":"Dipakai untuk menyatakan pantas saja atau tidak heran setelah mengetahui alasannya.","formula":"怪不得 + Kalimat","examples":[{"hz":"怪不得他今天没来，原来生病了。","py":"Guài bu de tā jīn tiān méi lái, yuán lái shēng bìng le.","id":"Pantas saja dia hari ini tidak datang, ternyata dia sakit."},{"hz":"怪不得你中文说得这么好，原来你在中国留学过。","py":"Guài bu de nǐ Zhōng wén shuō de zhè me hǎo, yuán lái nǐ zài Zhōng guó liú xué guò.","id":"Pantas saja bahasa Mandarinmu bagus sekali, ternyata kamu pernah belajar di Tiongkok."}]},{"hsk":6,"title":"巴不得 bā bu de","hanzi":"巴不得","pinyin":"bā bu de","desc":"Dipakai untuk menyatakan sangat berharap atau sangat menginginkan sesuatu terjadi.","formula":"Subjek + 巴不得 + Kalimat","examples":[{"hz":"我巴不得马上放假。","py":"Wǒ bā bu de mǎ shàng fàng jià.","id":"Saya sangat berharap liburan segera tiba."},{"hz":"他巴不得早点见到家人。","py":"Tā bā bu de zǎo diǎn jiàn dào jiā rén.","id":"Dia sangat ingin segera bertemu keluarganya."}]},{"hsk":6,"title":"恨不得 hèn bu de","hanzi":"恨不得","pinyin":"hèn bu de","desc":"Dipakai untuk menyatakan sangat ingin sampai-sampai terasa tidak sabar atau sangat kuat keinginannya.","formula":"Subjek + 恨不得 + Kata Kerja / Kalimat","examples":[{"hz":"我恨不得马上告诉大家这个好消息。","py":"Wǒ hèn bu de mǎ shàng gào su dà jiā zhè gè hǎo xiāo xi.","id":"Saya sangat ingin segera memberi tahu semua orang kabar baik ini."},{"hz":"他恨不得现在就回家。","py":"Tā hèn bu de xiàn zài jiù huí jiā.","id":"Dia sangat ingin langsung pulang sekarang."}]},{"hsk":6,"title":"难怪 nán guài","hanzi":"难怪","pinyin":"nán guài","desc":"Dipakai untuk menyatakan tidak heran, biasanya setelah mengetahui penyebab suatu keadaan.","formula":"难怪 + Kalimat","examples":[{"hz":"难怪他每天都很累，原来每天加班。","py":"Nán guài tā měi tiān dōu hěn lèi, yuán lái měi tiān jiā bān.","id":"Tidak heran dia setiap hari sangat lelah, ternyata setiap hari lembur."},{"hz":"难怪这家餐厅这么有名，菜真的很好吃。","py":"Nán guài zhè jiā cān tīng zhè me yǒu míng, cài zhēn de hěn hǎo chī.","id":"Tidak heran restoran ini sangat terkenal, makanannya memang sangat enak."}]},{"hsk":6,"title":"未免…了… wèi miǎn…le…","hanzi":"未免…了…","pinyin":"wèi miǎn…le…","desc":"Dipakai untuk menyatakan bahwa sesuatu agak terlalu atau terlalu berlebihan.","formula":"Subjek + 未免 + Terlalu… + 了","examples":[{"hz":"这个价格未免太贵了。","py":"Zhè gè jià gé wèi miǎn tài guì le.","id":"Harga ini agak terlalu mahal."},{"hz":"你这样说未免太直接了。","py":"Nǐ zhè yàng shuō wèi miǎn tài zhí jiē le.","id":"Cara bicaramu seperti itu agak terlalu langsung."}]},{"hsk":6,"title":"说不定 shuō bu dìng","hanzi":"说不定","pinyin":"shuō bu dìng","desc":"Dipakai untuk menyatakan mungkin saja atau siapa tahu.","formula":"说不定 + Kalimat","examples":[{"hz":"他今天说不定会来。","py":"Tā jīn tiān shuō bu dìng huì lái.","id":"Mungkin saja hari ini dia akan datang."},{"hz":"再试一次，说不定会成功。","py":"Zài shì yí cì, shuō bu dìng huì chéng gōng.","id":"Coba sekali lagi, siapa tahu akan berhasil."}]},{"hsk":6,"title":"免不了 miǎn bu liǎo","hanzi":"免不了","pinyin":"miǎn bu liǎo","desc":"Dipakai untuk menyatakan bahwa sesuatu tidak dapat dihindari.","formula":"Subjek + 免不了 + Kata Kerja / Kalimat","examples":[{"hz":"刚开始工作，免不了会紧张。","py":"Gāng kāi shǐ gōng zuò, miǎn bu liǎo huì jǐn zhāng.","id":"Saat baru mulai bekerja, rasa gugup tidak bisa dihindari."},{"hz":"一个人生活，免不了会遇到困难。","py":"Yì gè rén shēng huó, miǎn bu liǎo huì yù dào kùn nan.","id":"Hidup sendiri, tidak bisa menghindari berbagai kesulitan."}]},{"hsk":6,"title":"何必…呢…? hé bì…ne…?","hanzi":"何必…呢…?","pinyin":"hé bì…ne…?","desc":"Dipakai untuk menyatakan bahwa tidak perlu melakukan sesuatu atau untuk apa melakukan hal tersebut, biasanya berupa pertanyaan retoris.","formula":"何必 + Kata Kerja / Kalimat + 呢？","examples":[{"hz":"何必这么着急呢？","py":"Hé bì zhè me zháo jí ne?","id":"Untuk apa terburu-buru seperti ini?"},{"hz":"既然已经解决了，何必再担心呢？","py":"Jì rán yǐ jīng jiě jué le, hé bì zài dān xīn ne?","id":"Karena masalahnya sudah selesai, untuk apa khawatir lagi?"}]}];
